import Foundation
import Observation

@Observable
final class FeedModel {          // implicitly @MainActor (default isolation)
    var items: [Item] = []
    var isLoading = false
    var error: Error?

    func load() async {
        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            items = try await Self.fetchItems()
        } catch is CancellationError {
            // view went away; nothing to report
        } catch {
            self.error = error
        }
    }

    @concurrent
    private static func fetchItems() async throws -> [Item] {
        let (data, _) = try await URLSession.shared.data(from: feedURL)
        return Parser.parse(data)   // parsing runs off the main actor
    }
}
```

