  var items: [Item] = []
  var isLoading = false

  func load() async {
    guard !isLoading else { return }   // state can change across the await below
    isLoading = true
    defer { isLoading = false }

    do {
      let (data, _) = try await URLSession.shared.data(from: feedURL)
      items = Parser.parse(data)
    } catch {
      logger.error("Feed load failed: \(error)")
    }
  }
